import streamlit as st
from dataclasses import dataclass, field
from datetime import datetime, date, timedelta
from typing import List, Optional, Dict
import pandas as pd
from enum import Enum
import json

class PledgeStatus(Enum):
    PENDING = "Pending"
    PARTIALLY_PAID = "Partially Paid"
    PAID = "Paid"
    OVERDUE = "Overdue"
    CANCELLED = "Cancelled"

class DonorType(Enum):
    INDIVIDUAL = "Individual"
    CORPORATE = "Corporate"
    FOUNDATION = "Foundation"
    GOVERNMENT = "Government"

class PaymentMethod(Enum):
    CASH = "Cash"
    CHECK = "Check"
    CREDIT_CARD = "Credit Card"
    BANK_TRANSFER = "Bank Transfer"
    ONLINE = "Online"

@dataclass
class Payment:
    payment_id: str
    amount: float
    date: date
    method: PaymentMethod
    notes: str = ""
    receipt_number: Optional[str] = None

@dataclass
class Pledge:
    pledge_id: str
    donor_id: str
    amount: float
    pledge_date: date
    due_date: date
    campaign: str
    status: PledgeStatus
    payments: List[Payment] = field(default_factory=list)
    notes: str = ""

    @property
    def amount_paid(self) -> float:
        return sum(p.amount for p in self.payments)

    @property
    def amount_remaining(self) -> float:
        return self.amount - self.amount_paid

    @property
    def is_overdue(self) -> bool:
        return (self.due_date < date.today() and 
                self.status not in [PledgeStatus.PAID, PledgeStatus.CANCELLED])

    def update_status(self):
        if self.status == PledgeStatus.CANCELLED:
            return

        if self.amount_paid >= self.amount:
            self.status = PledgeStatus.PAID
        elif self.amount_paid > 0:
            self.status = PledgeStatus.PARTIALLY_PAID
        elif self.is_overdue:
            self.status = PledgeStatus.OVERDUE
        else:
            self.status = PledgeStatus.PENDING

@dataclass
class Donor:
    donor_id: str
    name: str
    donor_type: DonorType
    email: str
    phone: str
    address: str
    first_donation_date: Optional[date] = None
    tags: List[str] = field(default_factory=list)
    notes: str = ""

    @property
    def total_pledged(self) -> float:
        if 'donor_crm' in st.session_state:
            pledges = st.session_state.donor_crm.get_donor_pledges(self.donor_id)
            return sum(p.amount for p in pledges)
        return 0

    @property
    def total_donated(self) -> float:
        if 'donor_crm' in st.session_state:
            pledges = st.session_state.donor_crm.get_donor_pledges(self.donor_id)
            return sum(p.amount_paid for p in pledges)
        return 0

class DonorCRM:
    def __init__(self):
        self.donors: Dict[str, Donor] = {}
        self.pledges: Dict[str, Pledge] = {}
        self.next_donor_id = 1
        self.next_pledge_id = 1
        self.next_payment_id = 1

    def add_donor(self, donor: Donor) -> str:
        self.donors[donor.donor_id] = donor
        return donor.donor_id

    def add_pledge(self, pledge: Pledge) -> str:
        self.pledges[pledge.pledge_id] = pledge
        return pledge.pledge_id

    def add_payment(self, pledge_id: str, payment: Payment):
        if pledge_id in self.pledges:
            pledge = self.pledges[pledge_id]
            pledge.payments.append(payment)
            pledge.update_status()

    def get_donor_pledges(self, donor_id: str) -> List[Pledge]:
        return [p for p in self.pledges.values() if p.donor_id == donor_id]

    def get_overdue_pledges(self) -> List[Pledge]:
        overdue = []
        for pledge in self.pledges.values():
            if pledge.is_overdue:
                pledge.update_status()
                overdue.append(pledge)
        return overdue

    def get_campaign_summary(self, campaign: str) -> Dict:
        campaign_pledges = [p for p in self.pledges.values() if p.campaign == campaign]
        return {
            "total_pledged": sum(p.amount for p in campaign_pledges),
            "total_collected": sum(p.amount_paid for p in campaign_pledges),
            "num_pledges": len(campaign_pledges),
            "num_donors": len(set(p.donor_id for p in campaign_pledges))
        }

    def generate_donor_id(self) -> str:
        donor_id = f"D{self.next_donor_id:05d}"
        self.next_donor_id += 1
        return donor_id

    def generate_pledge_id(self) -> str:
        pledge_id = f"P{self.next_pledge_id:05d}"
        self.next_pledge_id += 1
        return pledge_id

    def generate_payment_id(self) -> str:
        payment_id = f"PAY{self.next_payment_id:05d}"
        self.next_payment_id += 1
        return payment_id

